        await page.goto(B+f'/admin/services/{sid}'); await setv(page,'title.en','ZZ Test Service EDITED'); await page.click('button:has-text("Save changes")'); await page.wait_for_selector('[role=status]:has-text("Saved")')
        s,h=pub('/en/services/zz-test-service'); chk('EDIT reaches the public page','ZZ Test Service EDITED' in h)
        s,h=pub('/fr/services/zz-test-service'); chk('editing English did NOT overwrite French','Service de test ZZ' in h and 'Fonction deux' in h)
        await page.goto(B+f'/admin/services/{sid}'); await setv(page,'description.fr',''); await page.click('button:has-text("Save changes")'); await page.wait_for_selector('[role=status]:has-text("Saved")')
