        await page.fill('[name=slug]','zz-other'); await page.fill('[name=image]','../../etc/passwd'); await page.click('button:has-text("Create service")'); await page.wait_for_timeout(900); await page.wait_for_selector('form [role=alert]'); chk('path-traversal image value rejected','Image' in await page.inner_text('form [role=alert]'))
        await page.fill('[name=image]','https://evil.example/x.png'); await page.click('button:has-text("Create service")'); await page.wait_for_timeout(900); await page.wait_for_selector('form [role=alert]'); chk('external image URL rejected','Image' in await page.inner_text('form [role=alert]'))
        await setv(page,'title.en',''); await page.fill('[name=image]',''); await page.click('button:has-text("Create service")'); await page.wait_for_timeout(900); await page.wait_for_selector('form [role=alert]'); chk('missing English title rejected','English text is required' in await page.inner_text('form [role=alert]'))
        chk('none of the rejected attempts created a row',one("select count(*) from services where slug in ('zz-other','Bad Slug!')")==0 and one("select count(*) from services")==7)
