        await page.goto(B+f'/admin/services/{sid}'); await page.locator('fieldset:has-text("Related projects") label:has-text("Skincare Store") input').check(); await page.click('button:has-text("Save changes")'); await page.wait_for_selector('[role=status]:has-text("Saved")')
