        chk('concurrent edit is detected (no silent overwrite)','changed by someone else' in await p2.inner_text('form [role=alert]') and one(f"select title->>'en' from services where id='{sid}'")=='Concurrent A'); await p2.close()
        # slug change safety
        await page.goto(B+f'/admin/services/{sid}'); await page.fill('[name=slug]','zz-renamed'); await page.click('button:has-text("Save changes")'); await page.wait_for_timeout(900); await page.wait_for_selector('form [role=alert]')
