        await page.goto(B+f'/admin/services/{sid}'); await page.click('button:has-text("Delete service")'); await page.wait_for_selector('[role=alert]:has-text("Unpublish")',timeout=8000)
        chk('deleting a PUBLISHED service is refused',one("select count(*) from services where slug='zz-renamed'")==1)
        await page.goto(B+'/admin/services'); await page.locator('tr:has-text("zz-renamed") button:has-text("Unpublish")').click(); await page.wait_for_selector('[role=status]:text-is("Unpublished. It is no longer visible on the public website.")'); await page.locator('tr:has-text("zz-renamed") a:has-text("Edit")').click(); await page.click('button:has-text("Delete service")'); await page.wait_for_url(re.compile(r'/admin/services\?ok'),timeout=8000)
        chk('after unpublishing, the service can be deleted (row + links gone)',one("select count(*) from services where slug='zz-renamed'")==0 and one(f"select count(*) from service_projects where service_id='{sid}'")==0)
