        await setv(page,'category_label.en','Test category'); await setv(page,'category_label.fr','Catégorie de test'); await setv(page,'category_label.ar','فئة الاختبار')
        await page.fill('[name=slug]','zz-test-project'); await page.fill('[name=category]','zztest'); await page.fill('[name=tech]','Next.js, Supabase, Next.js'); await page.fill('[name=thumbnail]','/images/pf-ecom.jpg'); await page.fill('[name=sort]','900'); await page.check('[name=published]')
        await page.locator('fieldset:has-text("Related services") label:has-text("Website Development") input').check()
        await page.click('button:has-text("Create project")'); await page.wait_for_url(re.compile(r'/admin/projects/[0-9a-f-]{36}'),timeout=10000); pid=re.search(r'/projects/([0-9a-f-]{36})',page.url).group(1)
        chk('project created (technologies de-duplicated)',one("select technologies from projects where slug='zz-test-project'")==['Next.js','Supabase'])
        s,h=pub('/en/portfolio/zz-test-project'); chk('public project page live immediately',s==200 and 'ZZ Test Project' in h and 'Concept project' in h)
        s,h=pub('/fr/portfolio'); chk('French portfolio shows French title + new filter category','Projet de test ZZ' in h and 'Catégorie de test' in h)
        s,h=pub('/ar/portfolio/zz-test-project'); chk('Arabic project page RTL + Arabic title','مشروع اختبار ZZ' in h and 'dir="rtl"' in h)
        s,h=pub('/en/services/web-development'); chk('linked from the related service page','ZZ Test Project' in h)
        await page.goto(B+'/en/portfolio'.replace(B,'')) if False else None
        pg2=await ctx.new_page(); await pg2.goto(B+'/en/portfolio',wait_until='networkidle'); n0=await pg2.locator('a.card').count(); await pg2.click('button:has-text("Test category")'); await pg2.wait_for_timeout(400)
        chk('portfolio filter works with the new DB category (5 → 1 → 5)',n0==5 and await pg2.locator('a.card').count()==1); await pg2.close()
